window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-aa5d51a01e72b8d9"]={"versions": [{"id": "FIG-aa5d51a01e72b8d9", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Testaufbau-Diagramm zur Veranschaulichung der Abbildung einer Systemtest-Implementierung (Map to System Test implementation) auf zwei Steuergeräte eines Prüflings sowie ein externes Testsystem. Das Diagramm gliedert sich in das „System under test“ mit zwei Zielsystemen („ECU1“ und „ECU2“) und das externe „Test System“ („Jenkins“), die über ein physisches Kommunikationsnetzwerk miteinander gekoppelt sind. Zudem erfolgt eine logische Testrolleneinteilung in „Upper tester“ und „Implementation Under Test“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst drei Hauptblöcke:</p>\n<ul class=\"fig-list\"><li><strong>System under test</strong>:\n<ul class=\"fig-list\"><li><strong>ECU1</strong>: Hardwarebasis „Intel MinnowBoard“, darauf das Betriebssystem „Linux with Real-time Patches“, Betriebssystem- und C-Bibliotheken „POXIS libs (libc, ...)“, die Middleware-Komponente „vSomeIP“, die AUTOSAR-Laufzeitumgebung „ARA“ sowie als Applikationsebene der Upper Tester „Video Data“.\n</li><li><strong>ECU2</strong>: Hardwarebasis „Renesas R-CAR H3 ULCB“, darauf „Linux with Real-time Patches“, „POXIS libs (libc, ...)“, „vSomeIP“, „ARA“ sowie als Applikation „System Test Applications“.\n</li><li>Logische Umrahmungen fassen „Video Data“ und „System Test Applications“ als „Upper tester“ zusammen; die Zwischenschichten von ARA über vSomeIP und POSIX-Bibliotheken bis zum Linux-Kernel bilden die „Implementation Under Test“.\n</li></ul>\n</li><li><strong>Test System (Jenkins)</strong>:\n<ul class=\"fig-list\"><li>Hardwarebasis „PC“, Betriebssystem „Linux“, Testautomatisierungs-/Ausführungsumgebung „Jenkins“ sowie die Testanwendung „CM Tester“.\n</li></ul>\n</li><li><strong>Netzwerk</strong>:\n<ul class=\"fig-list\"><li>Verbindendes Medium „Network (e.g. Ethernet)“.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Verbindungswege</strong>:\n<ul class=\"fig-list\"><li>Gestrichelte rote Linien stellen Kommunikations- und Datenflusspfade dar:\n<ul class=\"fig-list\"><li>Von Netzwerk zu Linux-Kernel auf ECU1, ECU2 und PC.\n</li><li>Von Linux-Kernel über vSomeIP zur ARA-Schicht auf beiden ECUs.\n</li><li>Direkte Pfade von Linux bzw. Netzwerk über ARA direkt in die Applikationsebene („Video Data“, „System Test Applications“).\n</li><li>Vom Linux-Host des PCs über Jenkins in den „CM Tester“.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Prüfablauf wird über das externe Testsystem gesteuert:</p>\n<ul class=\"fig-list\"><li>Der „CM Tester“ initiiert und überwacht über Jenkins und die Linux-Netzwerkschnittstelle Testnachrichten über das Ethernet-Netzwerk an das „System under test“.\n</li><li>Auf den Ziel-Steuergeräten (ECU1 und ECU2) empfängt der Linux-Kernel die Testdaten und leitet diese entweder über den SOME/IP-Stack (vSomeIP) und ARA an die Testapplikationen weiter oder bedient Schnittstellen direkt.\n</li><li>Die Upper-Tester-Applikationen („Video Data“ auf ECU1 und „System Test Applications“ auf ECU2) interagieren über die ARA-Schnittstellen mit der Plattform, führen die Systemtest-Szenarien aus und melden Ergebnisse bzw. Teststatus über das Netzwerk an den CM Tester / Jenkins zurück.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Nicht-normatives Übersichtsschaubild aus dem Technischen Bericht (TR) der AUTOSAR Adaptive Platform zur Testarchitektur. Entwickler und Integratoren müssen beachten:</p>\n<ul class=\"fig-list\"><li>Realitätsnahe Heterogenität der Hardware-Plattformen: Unterschiedliche Zielplattformen (x86-basiertes Intel MinnowBoard und ARM-basiertes Renesas R-CAR H3 ULCB) erfordern angepasste Linux-Kernel mit Real-Time-Patches (PREEMPT_RT).\n</li><li>POSIX-Konformität: Die Plattform stützt sich auf Standard-POSIX-C-Bibliotheken (libc), worauf Middleware-Komponenten wie SOME/IP aufsetzen.\n</li><li>Upper-Tester-Konzept: Zur Durchführung von Systemtests auf der Adaptive Platform müssen dedizierte Testanwendungen (Upper Tester) auf den Zielgeräten deployt werden, die direkt gegen ARA-Schnittstellen arbeiten.\n</li></ul>"}, {"id": "FIG-92120f1c111e83a3", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Testaufbau-Diagramm zur Veranschaulichung der Abbildung einer Systemtest-Implementierung (Map to System Test implementation) auf zwei Steuergeräte eines Prüflings sowie ein externes Testsystem. Das Diagramm gliedert sich in das „System under test“ mit zwei Zielsystemen („ECU1“ und „ECU2“) und das externe „Test System“ („Jenkins“), die über ein physisches Kommunikationsnetzwerk miteinander gekoppelt sind. Zudem erfolgt eine logische Testrolleneinteilung in „Upper tester“ und „Implementation Under Test“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst drei Hauptblöcke:</p>\n<ul class=\"fig-list\"><li><strong>System under test</strong>:\n<ul class=\"fig-list\"><li><strong>ECU1</strong>: Hardwarebasis „Intel MinnowBoard“, darauf das Betriebssystem „Linux with Real-time Patches“, System- und C-Bibliotheken „POSIX libs (libc, ...)“, die Middleware-Komponente „vSomeIP“, die AUTOSAR-Laufzeitumgebung „ARA“ sowie als Applikationsebene der Upper Tester „System Test Applications“.\n</li><li><strong>ECU2</strong>: Hardwarebasis „Renesas R-CAR H3 ULCB“, darauf „Linux with Real-time Patches“, „POSIX libs (libc, ...)“, „vSomeIP“, „ARA“ sowie als Applikation „System Test Applications“.\n</li><li>Logische Umrahmungen fassen die „System Test Applications“ beider Steuergeräte als „Upper tester“ zusammen; die Zwischenschichten von ARA über vSomeIP und POSIX-Bibliotheken bis zum Linux-Kernel bilden die „Implementation Under Test“.\n</li></ul>\n</li><li><strong>Test System (Jenkins)</strong>:\n<ul class=\"fig-list\"><li>Hardwarebasis „PC“, Betriebssystem „Linux“, Testautomatisierungs-/Ausführungsumgebung „Jenkins“ sowie die Testanwendung „CM Tester“.\n</li></ul>\n</li><li><strong>Netzwerk</strong>:\n<ul class=\"fig-list\"><li>Verbindendes Medium „Network (e.g. Ethernet)“.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Verbindungswege</strong>:\n<ul class=\"fig-list\"><li>Gestrichelte rote Linien stellen Kommunikations- und Datenflusspfade dar:\n<ul class=\"fig-list\"><li>Von Netzwerk zu Linux-Kernel auf ECU1, ECU2 und PC.\n</li><li>Von Linux-Kernel über vSomeIP zur ARA-Schicht auf beiden ECUs.\n</li><li>Direkte Pfade von Linux bzw. Netzwerk über ARA direkt in die Applikationsebene („System Test Applications“ auf ECU1 und ECU2).\n</li><li>Vom Linux-Host des PCs über Jenkins in den „CM Tester“.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Prüfablauf wird über das externe Testsystem gesteuert:</p>\n<ul class=\"fig-list\"><li>Der „CM Tester“ initiiert und überwacht über Jenkins und die Linux-Netzwerkschnittstelle Testnachrichten über das Ethernet-Netzwerk an das „System under test“.\n</li><li>Auf den Ziel-Steuergeräten (ECU1 und ECU2) empfängt der Linux-Kernel die Testdaten und leitet diese entweder über den SOME/IP-Stack (vSomeIP) und ARA an die Testapplikationen weiter oder bedient Schnittstellen direkt.\n</li><li>Die Upper-Tester-Applikationen („System Test Applications“ auf ECU1 und ECU2) interagieren über die ARA-Schnittstellen mit der Plattform, führen die Systemtest-Szenarien aus und melden Ergebnisse bzw. Teststatus über das Netzwerk an den CM Tester / Jenkins zurück.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Nicht-normatives Übersichtsschaubild aus dem Technischen Bericht (TR) der AUTOSAR Adaptive Platform zur Testarchitektur. Entwickler und Integratoren müssen beachten:</p>\n<ul class=\"fig-list\"><li>Realitätsnahe Heterogenität der Hardware-Plattformen: Unterschiedliche Zielplattformen (x86-basiertes Intel MinnowBoard und ARM-basiertes Renesas R-CAR H3 ULCB) erfordern angepasste Linux-Kernel mit Real-Time-Patches (PREEMPT_RT).\n</li><li>POSIX-Konformität: Die Plattform stützt sich auf Standard-POSIX-C-Bibliotheken (libc), worauf Middleware-Komponenten wie SOME/IP aufsetzen.\n</li><li>Upper-Tester-Konzept: Zur Durchführung von Systemtests auf der Adaptive Platform müssen dedizierte Testanwendungen (Upper Tester) auf den Zielgeräten deployt werden, die direkt gegen ARA-Schnittstellen arbeiten.\n</li></ul>"}], "trans": [{"from": "FIG-aa5d51a01e72b8d9", "to": "FIG-92120f1c111e83a3", "fr": "R19-03", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Oberste Anwendungskomponente auf ECU1: Beschriftung von „Video Data“ in „System Test Applications“ geändert.\n</li><li>Mittlere Bibliotheks-Schicht auf ECU1: Tippfehlerkorrektur in der Beschriftung von „POXIS libs (libc, ...)“ zu „POSIX libs (libc, ...)“.\n</li></ul>"}]};
